#include "ksSerialIrqTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
#include <utility>
int main(){using T=ks::SerialIrqTask;using S=T::Stage;using W=T::Write;using R=T::Read;unsigned cases=0;auto verify=[&](unsigned kind,unsigned producer,unsigned consumer,unsigned status,unsigned data,unsigned ret){T t(static_cast<T::Kind>(kind));unsigned used=0,children=0;std::vector<std::pair<W,unsigned>>writes;std::vector<R>reads;auto clock=[&](T::Clock c){return c==T::Clock::Return?ret:c==T::Clock::PortWrite?1u:t.dataAddress()>=0xfffd10?1u:3u;};while(t.stage()!=S::Complete){if(t.awaiting()){++children;t.resumeChild();continue;}auto cost=t.nextClocks(clock);if(t.advanceBefore(cost-1,[](R){return 0;},[](W,uint16_t){},clock))throw std::runtime_error("early");used+=t.advanceBefore(cost,[&](R r){reads.push_back(r);return r==R::Status?status:r==R::Producer?producer:r==R::Consumer?consumer:data;},[&](W w,uint16_t v){writes.emplace_back(w,v);},clock);}std::vector<std::pair<W,unsigned>>expected;std::vector<R>er;unsigned clocks=0,next=(producer+1)&255,dr=clock(T::Clock::DataRead),dw=clock(T::Clock::DataWrite);if(kind==0){expected={{W::Status,status&0xc7},{W::Error,2}};er={R::Status};clocks=48+ret;}else if(kind==1){expected={{W::Status,status&0xbf}};er={R::Status,R::Receive};if(data!=248){expected.emplace_back(W::Data,data);er.push_back(R::Producer);er.push_back(R::Consumer);expected.emplace_back(consumer==next?W::Error:W::Producer,consumer==next?2:next);clocks=(consumer==next?219:222)+dw+ret;}else clocks=164+ret;if(children!=unsigned(data==248))throw std::runtime_error("MIDI clock special dispatch");}else{er={R::Consumer,R::Producer};if(consumer==producer){expected={{W::Control,0x70}};clocks=83+ret;}else{expected={{W::Consumer,(consumer+1)&255},{W::Transmit,data},{W::Status,status&0x7f}};er.push_back(R::Data);er.push_back(R::Status);clocks=173+dr+ret;}}if(writes!=expected||reads!=er||used!=clocks)throw std::runtime_error("IRQ writes/reads/clocks");++cases;};for(unsigned ret:{17u,23u}){for(unsigned kind=0;kind<3;++kind)for(unsigned status=0;status<256;++status)for(unsigned data=0;data<256;++data)verify(kind,1,255,status,data,ret);for(unsigned kind=1;kind<3;++kind)for(unsigned producer=0;producer<256;++producer)for(unsigned consumer=0;consumer<256;++consumer)verify(kind,producer,consumer,255,127,ret);}std::cout<<"PASS: "<<cases<<" pure serial-IRQ properties\n";}
